import json
from pathlib import Path
from sympy import Rational
S='9701-4.1'; K=[S+'.'+str(i) for i in (1,2,3)]
R=Rational(831,100)
bank={x['id']:x for x in json.loads(Path('build/work/mcq/9701.tagged.json').read_text())}
mis=[
{'id':'m1','kc':K[0],'statement':'Gas pressure is caused by molecules colliding with one another only.','refutation':'Pressure on a container is force per unit area caused by collisions with its walls.','contrast':'Each wall collision changes molecular momentum and exerts a force on the wall.','source':'research'},
{'id':'m2','kc':K[1],'statement':'Ideal gas molecules have no mass.','refutation':'Their own volume is treated as zero; their mass is not zero.','contrast':'Ideal molecules still have momentum and cause pressure.','source':'research'},
{'id':'m3','kc':K[1],'statement':'Intermolecular attraction does not affect departure from ideal behaviour.','refutation':'Attractive forces make real gases deviate from the ideal model, especially at lower temperature.','contrast':'Steam deviates more than ammonia under the stated conditions because its hydrogen bonding is stronger.','source':'ER 9701 s22 P12 Q7'},
{'id':'m4','kc':K[2],'statement':'Volume in dm³ can be inserted directly with pressure in Pa and R in J K⁻¹ mol⁻¹.','refutation':'Convert volume to m³ so pV has units of joules.','contrast':'1.00 dm³ equals 1.00 × 10⁻³ m³.','source':'research'},
{'id':'m5','kc':K[2],'statement':'Moles of gas from pV=nRT always equal moles of the starting reagent.','refutation':'Use the balanced equation after calculating gas moles.','contrast':'Four KNO₃ units form eight gas molecules, so KNO₃ amount is half the gas amount.','source':'ER 9701 s22 P11 Q7'}]
items=[]
def mc(k,stem,opts,ans,why,d={},difficulty=2,cmd='Identify'):
 i=len([x for x in items if x['source']['type']=='generated'])+1
 items.append({'id':f'{S}-i{i:02d}','kcs':[k],'kind':'mcq','difficulty':difficulty,'command_word':cmd,'source':{'type':'generated'},'stem':stem,'options':dict(zip('ABCD',opts)),'answer':ans,'marks':1,'explanation':why,'hints':['Focus on the physical cause or the equation involved.','Check which quantities act on the container wall or enter $pV=nRT$.','Eliminate choices that contradict the model or its units.'],'distractors':d,'shuffle':True})
mc(K[0],'Explain the immediate origin of pressure exerted by a gas on its container.',['Molecular collisions with the container wall','Collisions between molecules alone','The weight of all molecules alone','Attraction between molecules and the wall'],'A','Molecules change momentum when they strike the wall; the resulting force per unit area is pressure.',{'B':'m1'},3,'Explain')
mc(K[0],'State what each molecular collision with a rigid wall transfers to the wall.',['Momentum','Mass','Moles','Temperature'],'A','A molecule changes momentum at the wall and exerts a force on it.',{},2,'State')
mc(K[0],'Predict the effect of more frequent wall collisions, with the momentum change per collision unchanged.',['Pressure increases','Pressure falls','Pressure becomes zero','Pressure is unchanged'],'A','More collisions per second increase the average wall force and hence pressure.',{},3,'Predict')
mc(K[0],'Explain why gas pressure acts on the side walls of a sealed vessel.',['Moving molecules collide with every wall','Only gravity pushes molecules sideways','Molecules exert pressure without moving','Only molecule–molecule collisions act on walls'],'A','Random molecular motion brings molecules into collision with side walls as well as the base.',{'D':'m1'},4,'Explain')
mc(K[0],'Identify the quantity that directly determines pressure at a given wall area.',['Average force on the wall','Total molecular mass alone','Number of intermolecular collisions alone','Volume of each ideal particle'],'A','Pressure is force divided by area; wall collisions create that force.',{'C':'m1'})
mc(K[0],'Describe what happens to a molecule when it rebounds from a container wall.',['Its momentum changes and the wall experiences a force','Its mass becomes zero','It ceases moving permanently','It attracts all other molecules'],'A','The rebound changes molecular momentum; Newton’s third law gives a force on the wall.',{},4,'Describe')
mc(K[1],'State the two defining ideal-gas particle assumptions.',['Zero particle volume and no intermolecular attraction','Zero particle mass and no collisions','Finite particle volume and strong attractions','No molecular motion and no collisions'],'A','Ideal particles are modelled as having negligible own volume and no intermolecular forces of attraction.',{'B':'m2','C':'m3'},2,'State')
mc(K[1],'Identify what is treated as zero for an ideal gas molecule.',['Its own volume','Its mass','Its momentum during motion','Its number of collisions'],'A','The ideal model assigns zero particle volume, not zero mass.',{'B':'m2'})
mc(K[1],'Predict when a real gas is most likely to approximate ideal behaviour.',['High temperature and low pressure','Low temperature and high pressure','Low temperature and low pressure','High pressure with strong attractions'],'A','High temperature reduces the relative effect of attractions; low pressure separates particles.',{'B':'m3'},4,'Predict')
mc(K[1],'Explain why a gas with stronger attractions departs more from ideal behaviour.',['Its molecules exert intermolecular forces absent from the ideal model','Its molecules have zero mass','Its molecules cannot hit walls','Its pressure is always zero'],'A','Intermolecular attraction violates an ideal-gas assumption and changes the pressure–volume relation.',{'B':'m2'},4,'Explain')
mc(K[2],'State the value and units of the molar gas constant used in $pV=nRT$.',['8.31 J K⁻¹ mol⁻¹','8.31 J K mol⁻¹','24.0 dm³ mol⁻¹','6.02 × 10²³ mol⁻¹'],'A','The data sheet gives $R=8.31\,\mathrm{J\,K^{-1}\,mol^{-1}}$.',{},1,'State')
mc(K[2],'Identify the correct SI conversion of $250\,\mathrm{cm^3}$ for $pV=nRT$.',['2.50 × 10⁻⁴ m³','2.50 × 10⁻¹ m³','250 m³','2.50 × 10⁵ m³'],'A','One cubic centimetre is $10^{-6}\,\mathrm{m^3}$, so multiply 250 by $10^{-6}$.',{'B':'m4'},2,'Identify')
# Numeric facts and distractors are computed from exact rational quantities.
p=Rational(100000); V=Rational(240,10**6); T=Rational(310)
n=p*V/(R*T)
assert round(float(n),5)==0.00932
mc(K[2],'Calculate the amount of ideal gas in $240\,\mathrm{cm^3}$ at $310\,\mathrm{K}$ and $100\,\mathrm{kPa}$.',['9.32 × 10⁻³ mol','9.32 mol','9.32 × 10⁻⁶ mol','0.0781 mol'],'A',f'Convert volume to $2.40\\times10^{{-4}}\\,\\mathrm{{m^3}}$ and pressure to $100000\\,\\mathrm{{Pa}}$; $n=pV/RT={float(n):.3g}\\,\\mathrm{{mol}}$.',{'B':'m4'},3,'Calculate')
sel=['9701_s22_12_q7','9701_w21_11_q6','9701_s19_12_q6','9701_w25_13_q11','9701_w24_12_q7','9701_w20_12_q7','9701_w19_12_q5','9701_s25_12_q12','9701_s24_12_q7','9701_s24_11_q7','9701_w22_12_q15','9701_s22_11_q7']
exp=['Steam has the strongest effective hydrogen bonding here; A (ammonia) also hydrogen-bonds but less strongly.','Ammonia has hydrogen bonding and deviates most; CO₂ lacks that strong interaction.','Y limits the reaction: 3 mol Y forms 3 mol Z, leaving 1.5 mol X; 4.5 mol at 393 K in 0.001 m³ gives 1.47 × 10⁷ Pa. B uses an incorrect final mole count.','One gram of N₂ is 1/28 mol; p=nRT/V at 313 K and 0.002 m³ gives 46 400 Pa. D doubles the answer.','Use 1/28 mol, 323 K and 202 000 Pa: V≈470 cm³. D uses half the pressure.','Convert 12.0 kg He to 3000 mol; pV=nRT gives 897 m³, or 897 000 dm³. A misses the m³-to-dm³ conversion.','Use Mᵣ=mRT/pV with V=4.50 × 10⁻⁵ m³ and T=373 K: Mᵣ≈119. B does not use the full conversion correctly.','At 310 K, 100 000 Pa and 2.40 × 10⁻⁴ m³, n=9.32 × 10⁻³ mol. A is a factor of 1000 too small.','One gram N₂ is 1/28 mol; V=nRT/p≈0.799 dm³. C roughly doubles the gas amount.','For F₂, Mᵣ=38; density pMᵣ/RT≈1.50 g dm⁻³. C overestimates it.','At constant temperature p is inversely proportional to V, so D is the reciprocal curve. A depicts the wrong dependence.','The gas amount is 9.63 × 10⁻⁴ mol; four KNO₃ form eight gas molecules, hence KNO₃ is half this amount. B omits the mole ratio.']
for j,(qid,why) in enumerate(zip(sel,exp),1):
 b=bank[qid]
 x={'id':f'{S}-p{j:02d}','kcs':[k for k in b['kcs'] if k in K],'kind':'mcq','difficulty':3,'command_word':'Identify','source':{'type':'past','ref':b['ref'],'qid':qid},'stem':b['stem'],'options':b['options'],'answer':b['answer'],'marks':1,'explanation':why,'hints':['Identify the physical assumption or write $pV=nRT$.','Convert pressure, volume and temperature to SI units.','For reactions, apply the balanced mole ratio after finding gas moles.'],'distractors':{}}
 if b.get('image'):x['image']=b['image']
 if qid=='9701_s22_12_q7':x['distractors']={'A':'m3'}
 if qid=='9701_s22_11_q7':x['distractors']={'B':'m5'}
 if qid=='9701_w22_12_q15':x['distractors']={'A':'m4'}
 items.append(x)
M=Rational(175,1000)*R*373/(Rational(101300)*Rational(45,10**6))
assert round(float(M))==119
worked=[{'id':'we1','kc':K[2],'problem':'Calculate the relative molecular mass of a vapour: 0.175 g occupies 4.50 × 10⁻⁵ m³ at 373 K and 101300 Pa.','steps':[{'do':'Write $pV=nRT$ and $n=m/M_r$, so $M_r=mRT/(pV)$.','why':'The measured mass must be linked to amount of substance.'},{'do':'Substitute $M_r=0.175\times8.31\times373/(101300\times4.50\times10^{-5})$.','why':'Pressure and volume are in SI units.'},{'do':f'Calculate $M_r={float(M):.3g}$.','why':'Relative molecular mass has no unit and is given to three significant figures.','check':{'kind':'numeric','answer':{'value':round(float(M),3),'unit':'','sf_ok':[2,3]}}}],'faded':{'id':'we1f','problem':'Find $M_r$ when 0.100 g of vapour occupies 85.0 cm³ at 400 K and 101300 Pa.','answer':{'value':round(float(Rational(1,10)*R*400/(Rational(101300)*Rational(85,10**6))),3),'unit':'','sf_ok':[2,3]},'blank_from':1}}]
pack={'subtopic':S,'spec':'9701','version':1,'note':'Subjects/9701 Chemistry/04 States of matter/4.1 The gaseous state: ideal and real gases and pV = nRT.md','outline':'Moving gas molecules collide with container walls. Their momentum changes produce a force on each wall; force per unit area is pressure. Ideal particles have zero own volume and no intermolecular attraction, although they retain mass. Real gases approach this model at high temperature and low pressure. For an ideal gas, $pV=nRT$ with pressure in pascals, volume in cubic metres, temperature in kelvin and $R=8.31\,\mathrm{J\,K^{-1}\,mol^{-1}}$. For a gas of mass $m$, $n=m/M_r$, hence $M_r=mRT/(pV)$.','misconceptions':mis,'worked':worked,'items':items,'flashcards':[{'id':'fc1','kc':K[1],'front':'State the ideal-gas particle assumptions.','back':'Particles have zero volume and no intermolecular forces of attraction.'},{'id':'fc2','kc':K[2],'front':'State the ideal gas equation and the value of $R$.','back':'$pV=nRT$; $R=8.31\,\mathrm{J\,K^{-1}\,mol^{-1}}$.'}],'diagrams':[]}
p=Path('build/out/packs/9701/9701-4.1.json');p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(pack,ensure_ascii=False,indent=2))
